const input = $input.first().json;

if (input.error) {
  const message = typeof input.error === 'string' ? input.error : input.error.message || JSON.stringify(input.error);
  return [{ json: { content: `ERROR N8N (search): ${message}` } }];
}

const statusCode = Number(input.statusCode || 0);
if (statusCode >= 400) return [{ json: { content: `ERROR HTTP ${statusCode} en Bing RSS` } }];

const xml = String(input.body ?? input.data ?? '');
if (xml.length < 50) return [{ json: { content: `ERROR: respuesta vacía (len=${xml.length})` } }];

if (!/<rss\b|<feed\b/i.test(xml)) return [{ json: { content: `ERROR: Bing no devolvió RSS.` } }];

const decode = (value) => String(value ?? '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&#(\d+);/g, (_, number) => String.fromCodePoint(Number(number))).replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();

const results = [];
const itemRegex = /<item\b[^>]*>([\s\S]*?)<\/item>/gi;
let match;

while ((match = itemRegex.exec(xml)) !== null && results.length < 10) {
  const block = match[1];
  const titleMatch = block.match(/<title\b[^>]*>([\s\S]*?)<\/title>/i);
  const linkMatch = block.match(/<link\b[^>]*>([\s\S]*?)<\/link>/i);
  if (!titleMatch || !linkMatch) continue;

  const title = decode(titleMatch[1]);
  const url = decode(linkMatch[1]);

  if (title && /^https?:\/\//i.test(url)) results.push(`${results.length + 1}. ${title}\n   ${url}`);
}

if (!results.length) return [{ json: { content: `Bing RSS sin resultados utilizables.` } }];

return [{ json: { content: `Resultados (${results.length}):\n\n${results.join('\n\n')}` } }];
